import{c as t,Q as r,j as o,m as s}from"./chunks/framework.g_l1frA7.js";const h=JSON.parse('{"title":"Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"copilot/recipes.md","filePath":"copilot/recipes.md","lastUpdated":null}'),a={name:"copilot/recipes.md"};function i(n,e,l,c,p,d){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>Recipes are trusted, multi-step automations the Copilot can propose and you approve — short, readable, and reversible.</p><p>Examples:</p><ul><li>“Create next month’s envelopes from last month’s actuals.”</li><li>“Move $400/month to emergency fund for 6 months.”</li><li>“Roll over unspent groceries to Savings.”</li></ul><h2 id="how-recipes-work" tabindex="-1">How recipes work <a class="header-anchor" href="#how-recipes-work" aria-label="Permalink to &quot;How recipes work&quot;">​</a></h2><ol><li><strong>Discover</strong> — open <strong>Recipes</strong> or accept a Copilot suggestion. The runner (<code>finsight-agent::recipe_runner</code>) lists steps, expected effects, and required confirmations.</li><li><strong>Review</strong> — every tool call and argument is shown before execution via the same RPC dispatcher as any other action.</li><li><strong>Run</strong> — confirm; the runner executes the sequence and reports per-step results.</li><li><strong>Review again</strong> — post-execution a card appears with status and undo hints where applicable.</li></ol><h2 id="recipes-vs-rules" tabindex="-1">Recipes vs rules <a class="header-anchor" href="#recipes-vs-rules" aria-label="Permalink to &quot;Recipes vs rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Recipes</th><th>Rules</th></tr></thead><tbody><tr><td>Trigger</td><td>You do</td><td>Incoming rows do</td></tr><tr><td>Scope</td><td>Multi-step, cross-cutting</td><td>Single pattern → category/treatment</td></tr><tr><td>Confirmation</td><td>Per-recipe</td><td>Per-rule enable/disable</td></tr></tbody></table><p>Recipes are <strong>not</strong> silent — no step runs without your confirmation. Remove or edit a generated envelope, contribution, or transaction like any other ledger row.</p><p>See also: <a href="/FinSight/guide/recipes">Guide → Recipes</a>, <a href="/FinSight/automation/rules">Rules</a>.</p>',10)])])}const g=t(a,[["render",i]]);export{h as __pageData,g as default};
